"""Fixtures for the generated tests (generated by GenNAI)."""

import os
from pathlib import Path

import pytest
from playwright.sync_api import Error as PlaywrightError
from playwright.sync_api import sync_playwright

URL = 'http://127.0.0.1:52297/'
ACTION_TIMEOUT_MS = 5000
NAV_TIMEOUT_MS = 30000  # page loads can be much slower than actions
SHOTS = Path(__file__).resolve().parent.parent / "screenshots"


class PageUnavailable(Exception):
    """The page answered with an HTTP error, so element checks would be meaningless."""


@pytest.fixture(scope="session")
def browser():
    with sync_playwright() as p:
        b = p.chromium.launch(headless=os.environ.get("GENNAI_HEADED") != "1")
        yield b
        b.close()


@pytest.fixture
def page(browser):
    context = browser.new_context()
    context.set_default_timeout(ACTION_TIMEOUT_MS)
    page = context.new_page()
    response = page.goto(URL, wait_until="domcontentloaded", timeout=NAV_TIMEOUT_MS)
    if response is not None and response.status >= 400:
        raise PageUnavailable(f"{URL} returned HTTP {response.status}")
    yield page
    context.close()


@pytest.hookimpl(hookwrapper=True)
def pytest_runtest_makereport(item, call):
    report = (yield).get_result()
    page = item.funcargs.get("page")
    if report.when == "call" and report.failed and page is not None:
        try:
            SHOTS.mkdir(exist_ok=True)
            page.screenshot(path=str(SHOTS / f"{item.name}.png"))
        except PlaywrightError:
            pass
